/* Pixel Theme Stylesheet */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1a2e;
  --card-bg: #16213e;
  --pixel-accent: #0f3460;
  --text-main: #e94560;
  --text-bright: #ffffff;
  --text-muted: #8a8fa3;
  --border-color: #533483;
  --error-color: #ff4757;
  --shadow-color: #0b1021;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image: 
    linear-gradient(45deg, #151525 25%, transparent 25%), 
    linear-gradient(-45deg, #151525 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #151525 75%), 
    linear-gradient(-45deg, transparent 75%, #151525 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text-bright);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.converter-card {
  width: 100%;
  max-width: 480px;
  background: var(--card-bg);
  border: 4px solid var(--text-bright);
  box-shadow: 8px 8px 0px var(--shadow-color);
  padding: 24px;
  position: relative;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.pixel-banner {
  display: inline-block;
  background: var(--pixel-accent);
  color: var(--text-bright);
  font-weight: bold;
  font-size: 13px;
  padding: 4px 8px;
  margin-bottom: 8px;
  border: 2px solid var(--border-color);
  letter-spacing: 1px;
}

.title {
  font-size: 24px;
  font-weight: 900;
  color: var(--text-main);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0px var(--shadow-color);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 13px;
  color: var(--text-muted);
}

.converter-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.input-group {
  background: #111a33;
  border: 2px solid var(--border-color);
  padding: 16px;
  box-shadow: 4px 4px 0px var(--shadow-color);
}

.label {
  display: block;
  font-size: 13px;
  font-weight: bold;
  color: var(--text-bright);
  margin-bottom: 8px;
  letter-spacing: 0.5px;
}

input[type="text"] {
  width: 100%;
  padding: 12px;
  background-color: #0b1021;
  border: 2px solid var(--border-color);
  color: var(--text-bright);
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  outline: none;
  text-transform: uppercase;
  box-shadow: inset 2px 2px 0px rgba(0, 0, 0, 0.6);
  transition: border-color 0.1s ease;
}

input[type="text"]:focus {
  border-color: var(--text-main);
  background-color: #0d142b;
}

.output-box {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 2px dashed var(--pixel-accent);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  min-height: 28px;
}

.output-label {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: bold;
}

.result-value {
  font-size: 18px;
  font-weight: 900;
  color: #4ade80;
  word-break: break-all;
  text-align: right;
}

.result-value.invalid {
  color: var(--error-color);
}

.divider-icon {
  text-align: center;
  color: var(--text-main);
  font-size: 14px;
  letter-spacing: 4px;
  user-select: none;
}

.quick-actions {
  display: flex;
  gap: 12px;
  margin-top: 20px;
}

.pixel-btn {
  flex: 1;
  background: var(--pixel-accent);
  color: var(--text-bright);
  border: 2px solid var(--text-bright);
  padding: 10px 14px;
  font-family: inherit;
  font-size: 14px;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 3px 3px 0px var(--shadow-color);
  user-select: none;
  text-align: center;
}

.pixel-btn:hover {
  background: var(--text-main);
}

.pixel-btn:focus {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--shadow-color);
}

.card-footer {
  margin-top: 20px;
  text-align: center;
  font-size: 11px;
  color: var(--text-muted);
  border-top: 2px solid var(--pixel-accent);
  padding-top: 12px;
}

@media (max-width: 400px) {
  .converter-card {
    padding: 16px;
  }
  .title {
    font-size: 20px;
  }
  .result-value {
    font-size: 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const arabicInput = document.getElementById('arabic-input');
  const arabicResult = document.getElementById('arabic-result');
  const romanInput = document.getElementById('roman-input');
  const romanResult = document.getElementById('roman-result');
  const clearBtn = document.getElementById('btn-clear');
  const exampleBtn = document.getElementById('btn-example');

  const ROMAN_MAP = [
    { value: 1000, symbol: 'M' },
    { value: 900, symbol: 'CM' },
    { value: 500, symbol: 'D' },
    { value: 400, symbol: 'CD' },
    { value: 100, symbol: 'C' },
    { value: 90, symbol: 'XC' },
    { value: 50, symbol: 'L' },
    { value: 40, symbol: 'XL' },
    { value: 10, symbol: 'X' },
    { value: 9, symbol: 'IX' },
    { value: 5, symbol: 'V' },
    { value: 4, symbol: 'IV' },
    { value: 1, symbol: 'I' }
  ];

  const STRICT_ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  function integerToRoman(num) {
    if (typeof num !== 'number' || isNaN(num) || num < 1 || num > 3999 || !Number.isInteger(num)) {
      return null;
    }
    let remainder = num;
    let result = '';
    for (let i = 0; i < ROMAN_MAP.length; i++) {
      const item = ROMAN_MAP[i];
      while (remainder >= item.value) {
        result += item.symbol;
        remainder -= item.value;
      }
    }
    return result;
  }

  function romanToInteger(romanStr) {
    if (typeof romanStr !== 'string') return null;
    const str = romanStr.trim().toUpperCase();
    if (!str || !STRICT_ROMAN_REGEX.test(str)) {
      return null;
    }

    const charValues = {
      'I': 1,
      'V': 5,
      'X': 10,
      'L': 50,
      'C': 100,
      'D': 500,
      'M': 1000
    };

    let total = 0;
    for (let i = 0; i < str.length; i++) {
      const current = charValues[str[i]];
      const next = charValues[str[i + 1]];
      if (next && current < next) {
        total -= current;
      } else {
        total += current;
      }
    }
    return (total >= 1 && total <= 3999) ? total : null;
  }

  function updateArabicConversion() {
    const val = arabicInput.value.trim();
    if (!val) {
      arabicResult.textContent = '-';
      arabicResult.classList.remove('invalid');
      return;
    }

    const num = Number(val);
    if (/^\d+$/.test(val) && num >= 1 && num <= 3999) {
      const roman = integerToRoman(num);
      arabicResult.textContent = roman;
      arabicResult.classList.remove('invalid');
    } else {
      arabicResult.textContent = 'Not valid';
      arabicResult.classList.add('invalid');
    }
  }

  function updateRomanConversion() {
    const rawVal = romanInput.value.trim();
    if (!rawVal) {
      romanResult.textContent = '-';
      romanResult.classList.remove('invalid');
      return;
    }

    const num = romanToInteger(rawVal);
    if (num !== null) {
      romanResult.textContent = num.toString();
      romanResult.classList.remove('invalid');
    } else {
      romanResult.textContent = 'Not valid';
      romanResult.classList.add('invalid');
    }
  }

  arabicInput.addEventListener('input', updateArabicConversion);

  romanInput.addEventListener('input', () => {
    romanInput.value = romanInput.value.toUpperCase();
    updateRomanConversion();
  });

  clearBtn.addEventListener('click', () => {
    arabicInput.value = '';
    romanInput.value = '';
    arabicResult.textContent = '-';
    romanResult.textContent = '-';
    arabicResult.classList.remove('invalid');
    romanResult.classList.remove('invalid');
    arabicInput.focus();
  });

  exampleBtn.addEventListener('click', () => {
    const randomVal = Math.floor(Math.random() * 3999) + 1;
    arabicInput.value = randomVal.toString();
    updateArabicConversion();

    const romanVal = integerToRoman(randomVal);
    romanInput.value = romanVal;
    updateRomanConversion();
  });
});
